-- Native historical recap is an independent private lane. No provider/policy activation.
-- Canonical UUID references deliberately have no source FKs: no hidden row locks under epoch.
begin;
create table public.clinical_recap_epochs(pet_id uuid primary key,version bigint not null check(version>0));
create table public.clinical_recap_policies(version integer primary key check(version>0),status text not null check(status in('draft','approved')),consent_text text not null,retention_text text not null,generation_model text not null check(generation_model='gpt-6-luna'),reviewed_by uuid,reviewed_at timestamptz,created_at timestamptz not null default clock_timestamp(),check((status='draft'and reviewed_by is null and reviewed_at is null)or(status='approved'and reviewed_by is not null and reviewed_at is not null)));
create table public.clinical_recap_policy_actions(id uuid primary key,actor_id uuid not null,session_id uuid not null,request jsonb not null,request_hash text not null,receipt jsonb not null,created_at timestamptz not null default clock_timestamp());
create table public.clinical_recap_manifests(id uuid primary key,pet_id uuid not null,document jsonb not null,sha256 text not null,created_at timestamptz not null default clock_timestamp());
create table public.clinical_recap_jobs(id uuid primary key,actor_id uuid not null,session_id uuid not null,pet_id uuid not null,policy_version integer not null references public.clinical_recap_policies(version),manifest_id uuid not null unique references public.clinical_recap_manifests(id),manifest_sha256 text not null,previous_job_id uuid,source_note text not null,intent jsonb not null,output_id uuid,review_version integer not null default 1 check(review_version in(1,2)),created_at timestamptz not null default clock_timestamp());
create table public.clinical_recap_attempts(id uuid primary key,job_id uuid not null references public.clinical_recap_jobs(id),actor_id uuid not null,session_id uuid not null,sequence integer not null check(sequence between 1 and 6),model text not null,state text not null check(state in('claimed','sending','completed','failed','uncertain','superseded')),intent jsonb not null,lease_until timestamptz not null,result jsonb,result_hash text,error_code text,failure_details jsonb,provider_request_id text,created_at timestamptz not null default clock_timestamp(),finished_at timestamptz,unique(job_id,sequence));
create table public.clinical_recap_cancellations(family text not null check(family in('policy','reservation','attempt','review')),id uuid not null,actor_id uuid not null,session_id uuid not null,job_id uuid,intent jsonb,created_at timestamptz not null default clock_timestamp(),primary key(family,id));
create table public.clinical_recap_outputs(id uuid primary key references public.clinical_recap_attempts(id),job_id uuid not null unique references public.clinical_recap_jobs(id),manifest_sha256 text not null,payload jsonb not null,payload_sha256 text not null,provider_manifest jsonb not null,created_at timestamptz not null default clock_timestamp());
create table public.clinical_recap_reviews(id uuid primary key,job_id uuid not null unique references public.clinical_recap_jobs(id),output_id uuid not null unique references public.clinical_recap_outputs(id),reviewer_id uuid not null,session_id uuid not null,decision text not null check(decision in('accepted','rejected')),accepted_claims jsonb not null,review_note text not null,manifest_sha256 text not null,output_sha256 text not null,version integer not null default 2 check(version=2),created_at timestamptz not null default clock_timestamp());
create table public.clinical_recap_review_actions(id uuid primary key,actor_id uuid not null,session_id uuid not null,job_id uuid not null references public.clinical_recap_jobs(id),request jsonb not null,request_hash text not null,receipt jsonb not null,created_at timestamptz not null default clock_timestamp());
create index clinical_recap_jobs_patient on public.clinical_recap_jobs(pet_id,created_at desc,id desc);
create function public.clinical_recap_row_guard()returns trigger language plpgsql set search_path=public,pg_temp as $$begin
 if TG_OP in('DELETE','TRUNCATE')then raise exception 'Recap history is retained'using errcode='23514';end if;
 if TG_TABLE_NAME='clinical_recap_epochs'then if new.pet_id<>old.pet_id or new.version<>old.version+1 then raise exception 'Epoch must advance once'using errcode='23514';end if;
 elsif TG_TABLE_NAME='clinical_recap_jobs'then if(to_jsonb(new)-array['output_id','review_version'])is distinct from(to_jsonb(old)-array['output_id','review_version'])or(old.output_id is not null and new.output_id is distinct from old.output_id)or new.review_version<old.review_version then raise exception 'Captured recap identity is immutable'using errcode='23514';end if;
 else if(to_jsonb(new)-array['state','result','result_hash','error_code','failure_details','provider_request_id','finished_at'])is distinct from(to_jsonb(old)-array['state','result','result_hash','error_code','failure_details','provider_request_id','finished_at'])then raise exception 'Recap attempt identity is immutable'using errcode='23514';end if;end if;return new;
end $$;
do $$declare t text;begin foreach t in array array['clinical_recap_epochs','clinical_recap_policies','clinical_recap_policy_actions','clinical_recap_manifests','clinical_recap_jobs','clinical_recap_attempts','clinical_recap_cancellations','clinical_recap_outputs','clinical_recap_reviews','clinical_recap_review_actions']loop
 execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated,service_role',t);
 if t in('clinical_recap_epochs','clinical_recap_jobs','clinical_recap_attempts')then execute format('create trigger recap_row_guard before update or delete on public.%I for each row execute function public.clinical_recap_row_guard()',t);else execute format('create trigger recap_immutable before update or delete on public.%I for each row execute function public.guard_inquiry_history()',t);end if;
 execute format('create trigger recap_no_truncate before truncate on public.%I for each statement execute function public.native_correction_immutable()',t);end loop;end $$;
create function public.clinical_recap_hash(v jsonb)returns text language sql immutable strict set search_path=public,pg_temp as $$select encode(extensions.digest(convert_to(v::text,'UTF8'),'sha256'),'hex')$$;
create function public.clinical_recap_timestamp(v timestamptz)returns text language sql immutable strict set search_path=pg_catalog,pg_temp as $$select to_char(v at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')$$;
create function public.clinical_recap_refuse(p_code text,p_reasons jsonb default'[]',p_budgets jsonb default'[]',p_delay integer default null)returns void language plpgsql set search_path=public,pg_temp as $$declare st text;begin
 st:=case when p_code='authentication_required'then'PT401'when p_code in('forbidden','policy_unapproved')then'PT403'when p_code='not_found'then'PT404'when p_code in('invalid_request','empty_selection','budget_exceeded')then'PT422'when p_code='rate_limited'then'PT429'when p_code='operation_unavailable'then'PT503'else'PT409'end;
 raise exception 'Clinical recap request unavailable'using errcode=st,detail=jsonb_build_object('code',p_code,'source_reasons',p_reasons,'budget_violations',p_budgets,'retry_after_seconds',p_delay)::text;
end $$;
create function public.clinical_recap_keys(v jsonb,k text[])returns void language plpgsql immutable set search_path=public,pg_temp as $$begin if v is null or jsonb_typeof(v)<>'object'or not v?&k or(select count(*)from jsonb_object_keys(v))<>cardinality(k)then perform public.clinical_recap_refuse('invalid_request');end if;end $$;
create function public.clinical_recap_text(v jsonb,n integer,required boolean default true)returns boolean language sql immutable set search_path=public,pg_temp as $$select jsonb_typeof(v)='string'and public.clinical_note_text_length(v#>>'{}')<=n and(not required or public.clinical_note_nonblank(v#>>'{}'))$$;
create function public.clinical_recap_uuid(v jsonb)returns uuid language plpgsql immutable set search_path=public,pg_temp as $$begin if jsonb_typeof(v)is distinct from'string'or v#>>'{}'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'then perform public.clinical_recap_refuse('invalid_request');end if;return(v#>>'{}')::uuid;end $$;
create function public.clinical_recap_integer(v jsonb,lo integer default 1,hi integer default 2147483646)returns integer language plpgsql immutable set search_path=public,pg_temp as $$begin if jsonb_typeof(v)is distinct from'number'or v::text!~'^[0-9]+$'or(v::text)::numeric not between lo and hi then perform public.clinical_recap_refuse('invalid_request');end if;return(v::text)::integer;end $$;
create function public.clinical_recap_session_ok(a uuid,s uuid)returns boolean language sql stable security definer set search_path=public,pg_temp as $$select coalesce(public.is_active_staff(a)and exists(select 1 from auth.sessions where id=s and user_id=a and(not_after is null or not_after>clock_timestamp()))and exists(select 1 from auth.users where id=a and(banned_until is null or banned_until<=clock_timestamp())),false)$$;
create function public.clinical_recap_actor(a uuid)returns uuid language plpgsql stable security definer set search_path=public,pg_temp as $$declare s uuid;begin
 if auth.uid()is null then perform public.clinical_recap_refuse('authentication_required');end if;
 begin s:=(auth.jwt()->>'session_id')::uuid;exception when invalid_text_representation then s:=null;end;
 if a is distinct from auth.uid()or not public.clinical_recap_session_ok(a,s)then perform public.clinical_recap_refuse('forbidden');end if;return s;
end $$;
create function public.clinical_recap_lock(f text,id uuid default null)returns void language plpgsql set search_path=public,pg_temp as $$begin
 if current_setting('transaction_isolation')<>'read committed'then perform public.clinical_recap_refuse('invalid_request');end if;
 if f='policy'then perform pg_advisory_xact_lock(hashtextextended('clinical-recap-policy',0));elsif f='actor'then perform pg_advisory_xact_lock(hashtextextended('clinical-recap-actor:'||id::text,0));else perform pg_advisory_xact_lock(hashtextextended('clinical-recap-action:'||f||':'||id::text,0));end if;
end $$;
create function public.clinical_recap_epoch_lock(p_pet uuid)returns void language plpgsql security definer set search_path=public,pg_temp as $$begin
 perform pg_advisory_xact_lock(hashtextextended('clinical-recap-source:'||p_pet::text,0));perform 1 from clinical_recap_epochs where pet_id=p_pet for update;if not found then perform public.clinical_recap_refuse('source_unavailable','["source_unavailable"]');end if;
end $$;
create function public.clinical_recap_epoch_changed()returns trigger language plpgsql security definer set search_path=public,pg_temp as $$declare pet uuid;begin
 if TG_TABLE_NAME='clinical_addenda'then select pet_id into pet from clinical_encounters where id=NEW.encounter_id;
 elsif TG_TABLE_NAME='ezyvet_problem_extractions'then select pet_id into pet from patient_problems where id=NEW.problem_id;
 elsif TG_TABLE_NAME='pets'then pet:=NEW.id;else pet:=NEW.pet_id;end if;
 if pet is null then perform public.clinical_recap_refuse('source_unavailable','["source_unavailable"]');end if;
 perform pg_advisory_xact_lock(hashtextextended('clinical-recap-source:'||pet::text,0));
 if TG_TABLE_NAME='pets'and TG_OP='INSERT'then insert into clinical_recap_epochs(pet_id,version)values(pet,1);else update clinical_recap_epochs set version=version+1 where pet_id=pet;if not found then perform public.clinical_recap_refuse('source_unavailable','["source_unavailable"]');end if;end if;return NEW;
end $$;
-- Source rows are retained by existing guards. New trigger writes only the private epoch.
-- Block concurrent patient writes before the backfill snapshot until the INSERT
-- initializer is installed and this migration commits. Transactional DDL alone
-- would leave a gap if a patient committed between backfill and CREATE TRIGGER.
lock table public.pets in share row exclusive mode;
insert into public.clinical_recap_epochs(pet_id,version)select id,1 from public.pets;
do $$declare t text;begin foreach t in array array['pets','clinical_encounters','clinical_addenda','patient_problems','ezyvet_problem_extractions']loop execute format('create trigger zzz_clinical_recap_epoch after insert or update on public.%I for each row execute function public.clinical_recap_epoch_changed()',t);end loop;end $$;
create function public.clinical_recap_selection(v jsonb)returns void language plpgsql immutable set search_path=public,pg_temp as $$declare x jsonb;lastid text:='';d date;k text;begin
 perform public.clinical_recap_keys(v,array['encounter_ids','include_native_problems','visit_from','visit_to']);if jsonb_typeof(v->'encounter_ids')is distinct from'array'or jsonb_array_length(v->'encounter_ids')>20 or jsonb_typeof(v->'include_native_problems')is distinct from'boolean'then perform public.clinical_recap_refuse('invalid_request');end if;
 for x in select value from jsonb_array_elements(v->'encounter_ids')loop perform public.clinical_recap_uuid(x);if x#>>'{}'<=lastid then perform public.clinical_recap_refuse('invalid_request');end if;lastid:=x#>>'{}';end loop;
 foreach k in array array['visit_from','visit_to']loop if v->k<>'null'::jsonb then begin if jsonb_typeof(v->k)<>'string'or v->>k!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$'then perform public.clinical_recap_refuse('invalid_request');end if;d:=(v->>k)::date;if not isfinite(d)or to_char(d,'YYYY-MM-DD')<>v->>k then perform public.clinical_recap_refuse('invalid_request');end if;exception when datetime_field_overflow or invalid_datetime_format then perform public.clinical_recap_refuse('invalid_request');end;end if;end loop;
 if(v->>'visit_from')::date>(v->>'visit_to')::date then perform public.clinical_recap_refuse('invalid_request');end if;
end $$;
create function public.clinical_recap_collect(p_pet uuid,p_selection jsonb)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare data jsonb;s jsonb;all_sources jsonb:='[]';i integer:=0;characters integer:=0;bytes integer:=0;nextbytes integer;field jsonb;budgets jsonb;violations jsonb:='[]';k text;n integer;lim integer;begin
 perform public.clinical_recap_selection(p_selection);perform public.clinical_recap_epoch_lock(p_pet);
 -- ONE fresh native MVCC SELECT after epoch wait. No native tuple/FK locks.
 with patient as(select p.*from pets p join clients c on c.id=p.client_id where p.id=p_pet),
 enc as(select e.*from clinical_encounters e where e.pet_id=p_pet and e.status='signed'and e.id in(select(value#>>'{}')::uuid from jsonb_array_elements(p_selection->'encounter_ids'))and(p_selection->>'visit_from'is null or(e.visit_at at time zone'America/Denver')::date>=(p_selection->>'visit_from')::date)and(p_selection->>'visit_to'is null or(e.visit_at at time zone'America/Denver')::date<=(p_selection->>'visit_to')::date)),
 adds as(select a.*from clinical_addenda a join enc e on e.id=a.encounter_id),
 probs as(select p.*from patient_problems p where p.pet_id=p_pet and(p_selection->>'include_native_problems')::boolean and not exists(select 1 from ezyvet_problem_extractions x where x.problem_id=p.id)),
 sources as(
 select 'signed_encounter'::text kind,e.id,jsonb_build_object('kind','signed_encounter','id',e.id,'pet_id',p_pet,'version',e.version,'metadata',jsonb_build_object('visit_at',public.clinical_recap_timestamp(e.visit_at),'created_by',e.created_by,'signed_by',e.signed_by,'signed_at',public.clinical_recap_timestamp(e.signed_at)),'fields',jsonb_build_object('subjective',e.subjective,'objective',e.objective,'assessment',e.assessment,'plan',e.plan))v from enc e
 union all select'addendum',a.id,jsonb_build_object('kind','addendum','id',a.id,'pet_id',p_pet,'version',null,'metadata',jsonb_build_object('encounter_id',a.encounter_id,'created_by',a.created_by,'created_at',public.clinical_recap_timestamp(a.created_at)),'fields',jsonb_build_object('content',a.content))from adds a
 union all select'native_problem',p.id,jsonb_build_object('kind','native_problem','id',p.id,'pet_id',p_pet,'version',p.version,'metadata',jsonb_build_object('created_by',p.created_by,'created_at',public.clinical_recap_timestamp(p.created_at),'updated_by',p.updated_by,'updated_at',public.clinical_recap_timestamp(p.updated_at)),'fields',jsonb_build_object('title',p.title,'notes',p.notes,'status',p.status,'importance',p.importance,'onset_date',case when p.onset_date is not null then to_char(p.onset_date,'YYYY-MM-DD')end))from probs p)
 select jsonb_build_object('patient',(select jsonb_build_object('id',id,'version',version,'name',name,'species',species,'breed',breed,'dob',case when dob is not null then to_char(dob,'YYYY-MM-DD')end,'birth_date_precision',birth_date_precision,'sex',sex,'neuter_status',neuter_status,'archived_at',public.clinical_recap_timestamp(archived_at),'deceased_at',case when deceased_at is not null then to_char(deceased_at,'YYYY-MM-DD')end)from patient),
 'selection',p_selection,'sources',coalesce((select jsonb_agg(v order by kind,id)from sources),'[]'),
 'membership',jsonb_build_object('addenda_by_encounter',coalesce((select jsonb_agg(jsonb_build_object('encounter_id',e.id,'source_ids',coalesce((select jsonb_agg(a.id order by a.id)from adds a where a.encounter_id=e.id),'[]'))order by e.id)from enc e),'[]'),'native_problem_ids',case when(p_selection->>'include_native_problems')::boolean then coalesce((select jsonb_agg(id order by id)from probs),'[]')end),
 'exclusions',jsonb_build_object('outside_linked_problem_count',case when(p_selection->>'include_native_problems')::boolean then(select count(*)from patient_problems p where p.pet_id=p_pet and exists(select 1 from ezyvet_problem_extractions x where x.problem_id=p.id))end,'unsupported_families','["documents","outside_records","structured_labs","structured_treatments","structured_prescriptions","structured_vaccines","imaging"]'::jsonb),
 'budgets',jsonb_build_object('encounters',(select count(*)from enc),'problems',(select count(*)from probs),'source_units',(select count(*)from sources),'source_characters',0,'source_bytes',0))into data;
 if data->'patient'='null'::jsonb then perform public.clinical_recap_refuse('not_found');end if;
 if(data#>>'{budgets,encounters}')::integer<>jsonb_array_length(p_selection->'encounter_ids')then perform public.clinical_recap_refuse('source_unavailable','["source_unavailable"]');end if;
 for s in select value from jsonb_array_elements(data->'sources')loop i:=i+1;for field in select value from jsonb_each(s->'fields')loop if jsonb_typeof(field)='string'then characters:=characters+public.clinical_note_text_length(field#>>'{}');end if;end loop;all_sources:=all_sources||jsonb_build_array(s||jsonb_build_object('ref','src_'||lpad(i::text,4,'0'),'sha256',public.clinical_recap_hash(s)));end loop;
 data:=jsonb_set(data,'{sources}',all_sources);data:=jsonb_set(data,'{budgets,source_characters}',to_jsonb(characters));
 for n in 1..8 loop nextbytes:=octet_length(convert_to(data::text,'UTF8'));exit when nextbytes=bytes;bytes:=nextbytes;data:=jsonb_set(data,'{budgets,source_bytes}',to_jsonb(bytes));end loop;
 if(data#>>'{budgets,source_bytes}')::integer<>octet_length(convert_to(data::text,'UTF8'))then perform public.clinical_recap_refuse('operation_unavailable');end if;
 foreach k in array array['encounters','problems','source_units','source_characters','source_bytes']loop lim:=case k when'encounters'then 20 when'problems'then 40 when'source_units'then 64 when'source_characters'then 60000 else 240000 end;n:=(data#>>array['budgets',k])::integer;if n>lim then violations:=violations||jsonb_build_array(jsonb_build_object('dimension',k,'observed',n,'limit',lim));end if;end loop;
 if violations<>'[]'::jsonb then perform public.clinical_recap_refuse('budget_exceeded','[]',violations);end if;if i=0 then perform public.clinical_recap_refuse('empty_selection');end if;return data;
end $$;
create function public.clinical_recap_current(m jsonb)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare fresh jsonb;oldset jsonb:=m->'source_set';reasons jsonb:='[]';kind text;a jsonb;b jsonb;begin
 begin fresh:=public.clinical_recap_collect((oldset#>>'{patient,id}')::uuid,oldset->'selection');exception when others then return jsonb_build_object('source_status','unavailable','reasons','["source_unavailable"]'::jsonb);end;
 if public.clinical_recap_hash(fresh)=m->>'source_fingerprint'then return'{"source_status":"current","reasons":[]}'::jsonb;end if;
 if fresh->'patient'is distinct from oldset->'patient'then reasons:=reasons||'"patient_changed"'::jsonb;end if;
 foreach kind in array array['signed_encounter','addendum','native_problem']loop
 select coalesce(jsonb_agg(value order by value->>'id'),'[]')into a from jsonb_array_elements(fresh->'sources')where value->>'kind'=kind;select coalesce(jsonb_agg(value order by value->>'id'),'[]')into b from jsonb_array_elements(oldset->'sources')where value->>'kind'=kind;
 -- Source refs can shift when another family is inserted; compare original projections only.
 select coalesce(jsonb_agg(value-'ref'order by value->>'id'),'[]')into a from jsonb_array_elements(a);select coalesce(jsonb_agg(value-'ref'order by value->>'id'),'[]')into b from jsonb_array_elements(b);
 if a is distinct from b then reasons:=reasons||to_jsonb(case kind when'signed_encounter'then'encounters_changed'when'addendum'then'addenda_changed'else'problems_changed'end);end if;end loop;
 if fresh#>'{exclusions,outside_linked_problem_count}'is distinct from oldset#>'{exclusions,outside_linked_problem_count}'then reasons:=reasons||'"problem_eligibility_changed"'::jsonb;end if;
 if reasons='[]'::jsonb then reasons:='["source_unavailable"]';return jsonb_build_object('source_status','unavailable','reasons',reasons);end if;return jsonb_build_object('source_status','stale','reasons',reasons);
end $$;
create function public.clinical_recap_policy_view()returns jsonb language sql stable security definer set search_path=public,pg_temp as $$select to_jsonb(p)||jsonb_build_object('created_at',public.clinical_recap_timestamp(created_at),'reviewed_at',public.clinical_recap_timestamp(reviewed_at))from clinical_recap_policies p order by version desc limit 1$$;
insert into public.clinical_recap_policies(version,status,consent_text,retention_text,generation_model)values(1,'draft','Draft for Susan: authorize OpenAI processing of explicitly selected native signed encounter, complete addendum and optional native problem evidence into a source-cited historical recap. Review all claims and their dates; no normal findings, recommendations, chart writes or delivery are authorized.','Draft for Susan: retain immutable selected source snapshots, provenance, generated output and separate review history under the clinical record retention policy. Verify provider account handling before approval. Changed policy or invalid originating sessions prevent retaining newly received raw model output.','gpt-6-luna');
create function public.clinical_recap_attempt_view(a public.clinical_recap_attempts)returns jsonb language sql stable set search_path=public,pg_temp as $$select(to_jsonb(a)-array['session_id','result','sequence'])||jsonb_build_object('created_at',public.clinical_recap_timestamp(a.created_at),'finished_at',public.clinical_recap_timestamp(a.finished_at),'lease_until',public.clinical_recap_timestamp(a.lease_until))$$;
create function public.clinical_recap_job_view(p_id uuid)returns jsonb language sql stable security definer set search_path=public,pg_temp as $$select(to_jsonb(j)-array['session_id','intent'])||jsonb_build_object('created_at',public.clinical_recap_timestamp(j.created_at),'attempts',coalesce((select jsonb_agg(public.clinical_recap_attempt_view(a)order by sequence desc)from clinical_recap_attempts a where job_id=j.id),'[]'))from clinical_recap_jobs j where j.id=p_id$$;
create function public.clinical_recap_job_read(p_actor uuid,p_id uuid)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare j clinical_recap_jobs;m jsonb;c jsonb;begin
 select *into j from clinical_recap_jobs where id=p_id;if not found then perform public.clinical_recap_refuse('not_found');end if;select document into m from clinical_recap_manifests where id=j.manifest_id;c:=public.clinical_recap_current(m);
 return jsonb_build_object('actor_id',p_actor,'job',public.clinical_recap_job_view(j.id),'manifest',m,'policy',public.clinical_recap_policy_view(),'current',c,'output',(select to_jsonb(o)||jsonb_build_object('created_at',public.clinical_recap_timestamp(o.created_at))from clinical_recap_outputs o where job_id=j.id),'review',(select(to_jsonb(r)-'session_id')||jsonb_build_object('created_at',public.clinical_recap_timestamp(r.created_at))from clinical_recap_reviews r where job_id=j.id));
end $$;
create function public.read_clinical_recap_policy(p_actor_id uuid)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$begin perform public.clinical_recap_actor(p_actor_id);return jsonb_build_object('actor_id',p_actor_id,'policy',public.clinical_recap_policy_view());end $$;
create function public.recover_clinical_recap_policy(p_actor_id uuid,p_id uuid)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare a clinical_recap_policy_actions;c clinical_recap_cancellations;begin
 perform public.clinical_recap_actor(p_actor_id);select *into a from clinical_recap_policy_actions where id=p_id;if found then if a.actor_id<>p_actor_id then perform public.clinical_recap_refuse('forbidden');end if;return a.receipt;end if;select *into c from clinical_recap_cancellations where family='policy'and id=p_id;if found and c.actor_id<>p_actor_id then perform public.clinical_recap_refuse('forbidden');end if;return null;end $$;
create function public.cancel_clinical_recap_policy(p_actor_id uuid,p_id uuid)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare receipt jsonb;s uuid;begin
 s:=public.clinical_recap_actor(p_actor_id);if p_id is null then perform public.clinical_recap_refuse('invalid_request');end if;perform public.clinical_recap_lock('policy');perform pg_advisory_xact_lock(hashtextextended('clinical-recap-action:policy:'||p_id::text,0));s:=public.clinical_recap_actor(p_actor_id);receipt:=public.recover_clinical_recap_policy(p_actor_id,p_id);if receipt is not null then return jsonb_build_object('cancelled',false,'receipt',receipt);end if;
 insert into clinical_recap_cancellations(family,id,actor_id,session_id)values('policy',p_id,p_actor_id,s)on conflict(family,id)do nothing;return'{"cancelled":true,"receipt":null}'::jsonb;end $$;
create function public.save_clinical_recap_policy(p_actor_id uuid,p_id uuid,p_request jsonb)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare sid uuid;receipt jsonb;p jsonb;v integer;st text;begin
 sid:=public.clinical_recap_actor(p_actor_id);if p_id is null then perform public.clinical_recap_refuse('invalid_request');end if;perform public.clinical_recap_lock('policy');perform pg_advisory_xact_lock(hashtextextended('clinical-recap-action:policy:'||p_id::text,0));sid:=public.clinical_recap_actor(p_actor_id);
 receipt:=public.recover_clinical_recap_policy(p_actor_id,p_id);if receipt is not null then if(select request from clinical_recap_policy_actions where id=p_id)is distinct from p_request then perform public.clinical_recap_refuse('intent_conflict');end if;return receipt;end if;
 if exists(select 1 from clinical_recap_cancellations where family='policy'and id=p_id)then perform public.clinical_recap_refuse('action_cancelled');end if;if not public.has_role(p_actor_id,'ADMIN')then perform public.clinical_recap_refuse('forbidden');end if;
 perform public.clinical_recap_keys(p_request,array['expected_version','status','consent_text','retention_text','attest_reviewed']);p:=public.clinical_recap_policy_view();v:=public.clinical_recap_integer(p_request->'expected_version');if v<>(p->>'version')::integer then perform public.clinical_recap_refuse('policy_changed');end if;st:=p_request->>'status';
 if jsonb_typeof(p_request->'status')is distinct from'string'or st not in('draft','approved')or not coalesce(public.clinical_recap_text(p_request->'consent_text',4000),false)or not coalesce(public.clinical_recap_text(p_request->'retention_text',2000),false)or jsonb_typeof(p_request->'attest_reviewed')is distinct from'boolean'or(st='approved'and p_request->'attest_reviewed'<>'true'::jsonb)then perform public.clinical_recap_refuse('invalid_request');end if;
 sid:=public.clinical_recap_actor(p_actor_id);if not public.has_role(p_actor_id,'ADMIN')then perform public.clinical_recap_refuse('forbidden');end if;insert into clinical_recap_policies(version,status,consent_text,retention_text,generation_model,reviewed_by,reviewed_at)values(v+1,st,p_request->>'consent_text',p_request->>'retention_text','gpt-6-luna',case when st='approved'then p_actor_id end,case when st='approved'then clock_timestamp()end);
 receipt:=jsonb_build_object('id',p_id,'actor_id',p_actor_id,'request_hash',public.clinical_recap_hash(p_request),'policy',public.clinical_recap_policy_view());insert into clinical_recap_policy_actions(id,actor_id,session_id,request,request_hash,receipt)values(p_id,p_actor_id,sid,p_request,public.clinical_recap_hash(p_request),receipt);return receipt;
end $$;
create function public.preview_clinical_recap(p_actor_id uuid,p_pet_id uuid,p_selection jsonb)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare d jsonb;begin
 perform public.clinical_recap_actor(p_actor_id);perform public.clinical_recap_lock('policy');d:=public.clinical_recap_collect(p_pet_id,p_selection);perform public.clinical_recap_actor(p_actor_id);return jsonb_build_object('actor_id',p_actor_id,'pet_id',p_pet_id,'source_set',d,'source_fingerprint',public.clinical_recap_hash(d));end $$;
create function public.read_clinical_recap_job(p_actor_id uuid,p_id uuid)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare d jsonb;begin
 perform public.clinical_recap_actor(p_actor_id);perform public.clinical_recap_lock('policy');perform 1 from clinical_recap_jobs where id=p_id for share;if not found then perform public.clinical_recap_refuse('not_found');end if;d:=public.clinical_recap_job_read(p_actor_id,p_id);perform public.clinical_recap_actor(p_actor_id);return d;end $$;
create function public.read_clinical_recap_citation(p_actor_id uuid,p_job_id uuid,p_source_ref text)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare d jsonb;s jsonb;begin
 d:=public.read_clinical_recap_job(p_actor_id,p_job_id);select value into s from jsonb_array_elements(d#>'{manifest,source_set,sources}')where value->>'ref'=p_source_ref;if not found then perform public.clinical_recap_refuse('not_found');end if;return jsonb_build_object('actor_id',p_actor_id,'pet_id',d#>'{job,pet_id}','job_id',p_job_id,'manifest_id',d#>'{manifest,id}','manifest_sha256',d#>'{manifest,sha256}','source_ref',p_source_ref,'source',s,'current',d->'current');end $$;
create function public.reserve_clinical_recap(p_actor_id uuid,p_id uuid,p_request jsonb)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare sid uuid;j clinical_recap_jobs;c clinical_recap_cancellations;pet uuid;previous uuid;p jsonb;d jsonb;m jsonb;v integer;result jsonb;begin
 sid:=public.clinical_recap_actor(p_actor_id);if p_id is null then perform public.clinical_recap_refuse('invalid_request');end if;perform public.clinical_recap_lock('policy');perform public.clinical_recap_lock('actor',p_actor_id);perform public.clinical_recap_lock('reservation',p_id);sid:=public.clinical_recap_actor(p_actor_id);
 select *into j from clinical_recap_jobs where id=p_id for update;if found then if j.actor_id<>p_actor_id then perform public.clinical_recap_refuse('forbidden');end if;if j.intent is distinct from p_request then perform public.clinical_recap_refuse('intent_conflict');end if;result:=public.clinical_recap_job_read(p_actor_id,j.id);perform public.clinical_recap_actor(p_actor_id);return result;end if;
 select *into c from clinical_recap_cancellations where family='reservation'and id=p_id;if found then if c.actor_id<>p_actor_id then perform public.clinical_recap_refuse('forbidden');end if;perform public.clinical_recap_refuse('action_cancelled');end if;
 perform public.clinical_recap_keys(p_request,array['pet_id','expected_pet_version','policy_version','selection','expected_source_fingerprint','source_note','attest_authorized','previous_job_id']);pet:=public.clinical_recap_uuid(p_request->'pet_id');v:=public.clinical_recap_integer(p_request->'policy_version');perform public.clinical_recap_integer(p_request->'expected_pet_version');
 if not coalesce(public.clinical_recap_text(p_request->'source_note',1000),false)or p_request->'attest_authorized'is distinct from'true'::jsonb or jsonb_typeof(p_request->'expected_source_fingerprint')is distinct from'string'or p_request->>'expected_source_fingerprint'!~'^[a-f0-9]{64}$'then perform public.clinical_recap_refuse('invalid_request');end if;
 if p_request->'previous_job_id'<>'null'::jsonb then previous:=public.clinical_recap_uuid(p_request->'previous_job_id');if not exists(select 1 from clinical_recap_jobs where id=previous and pet_id=pet)then perform public.clinical_recap_refuse('identity_conflict');end if;end if;
 p:=public.clinical_recap_policy_view();if p->>'status'<>'approved'then perform public.clinical_recap_refuse('policy_unapproved');end if;if(p->>'version')::integer<>v then perform public.clinical_recap_refuse('policy_changed');end if;d:=public.clinical_recap_collect(pet,p_request->'selection');
 if(d#>>'{patient,version}')::integer<>(p_request->>'expected_pet_version')::integer then perform public.clinical_recap_refuse('identity_conflict');end if;if public.clinical_recap_hash(d)<>p_request->>'expected_source_fingerprint'then perform public.clinical_recap_refuse('source_changed');end if;
 sid:=public.clinical_recap_actor(p_actor_id);if(select count(*)from clinical_recap_jobs where actor_id=p_actor_id and created_at>clock_timestamp()-interval'1 hour')>=12 or(select count(*)from clinical_recap_jobs where actor_id=p_actor_id and created_at>clock_timestamp()-interval'1 day')>=100 then perform public.clinical_recap_refuse('rate_limited');end if;
 m:=jsonb_build_object('id',p_id,'contract_version','clinical-recap-source-v1','captured_at',public.clinical_recap_timestamp(clock_timestamp()),'source_fingerprint',public.clinical_recap_hash(d),'source_set',d);m:=m||jsonb_build_object('sha256',public.clinical_recap_hash(m));insert into clinical_recap_manifests(id,pet_id,document,sha256)values(p_id,pet,m,m->>'sha256');insert into clinical_recap_jobs(id,actor_id,session_id,pet_id,policy_version,manifest_id,manifest_sha256,previous_job_id,source_note,intent)values(p_id,p_actor_id,sid,pet,v,p_id,m->>'sha256',previous,p_request->>'source_note',p_request);result:=public.clinical_recap_job_read(p_actor_id,p_id);perform public.clinical_recap_actor(p_actor_id);return result;
end $$;
create function public.cancel_clinical_recap_reservation(p_actor_id uuid,p_id uuid)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare sid uuid;j clinical_recap_jobs;c clinical_recap_cancellations;begin
 sid:=public.clinical_recap_actor(p_actor_id);if p_id is null then perform public.clinical_recap_refuse('invalid_request');end if;perform public.clinical_recap_lock('policy');perform public.clinical_recap_lock('actor',p_actor_id);perform public.clinical_recap_lock('reservation',p_id);sid:=public.clinical_recap_actor(p_actor_id);
 select *into j from clinical_recap_jobs where id=p_id for update;if found then if j.actor_id<>p_actor_id then perform public.clinical_recap_refuse('forbidden');end if;return jsonb_build_object('cancelled',false,'job',public.clinical_recap_job_view(j.id));end if;
 select *into c from clinical_recap_cancellations where family='reservation'and id=p_id;if found and c.actor_id<>p_actor_id then perform public.clinical_recap_refuse('forbidden');end if;insert into clinical_recap_cancellations(family,id,actor_id,session_id)values('reservation',p_id,p_actor_id,sid)on conflict(family,id)do nothing;return'{"cancelled":true,"job":null}'::jsonb;end $$;
create function public.list_clinical_recap_sources(p_actor_id uuid,p_pet_id uuid,p_visit_from date default null,p_visit_to date default null,p_after jsonb default null)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare rows jsonb;total integer;cursor_at timestamptz;cursor_id uuid;begin
 perform public.clinical_recap_actor(p_actor_id);if p_visit_from>p_visit_to or(p_visit_from is not null and not isfinite(p_visit_from))or(p_visit_to is not null and not isfinite(p_visit_to))then perform public.clinical_recap_refuse('invalid_request');end if;if not exists(select 1 from pets p join clients c on c.id=p.client_id where p.id=p_pet_id)then perform public.clinical_recap_refuse('not_found');end if;
 if p_after is not null then perform public.clinical_recap_keys(p_after,array['visit_at','id']);cursor_id:=public.clinical_recap_uuid(p_after->'id');begin cursor_at:=(p_after->>'visit_at')::timestamptz;exception when others then perform public.clinical_recap_refuse('invalid_request');end;if cursor_at is null or not isfinite(cursor_at)then perform public.clinical_recap_refuse('invalid_request');end if;end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',e.id,'version',e.version,'visit_at',public.clinical_recap_timestamp(e.visit_at),'signed_at',public.clinical_recap_timestamp(e.signed_at),'addendum_count',(select count(*)from clinical_addenda where encounter_id=e.id))order by e.visit_at desc,e.id desc),'[]'),count(*)into rows,total from(select *from clinical_encounters where pet_id=p_pet_id and status='signed'and(p_visit_from is null or(visit_at at time zone'America/Denver')::date>=p_visit_from)and(p_visit_to is null or(visit_at at time zone'America/Denver')::date<=p_visit_to)and(p_after is null or(visit_at,id)<(cursor_at,cursor_id))order by visit_at desc,id desc limit 21)e;
 return jsonb_build_object('actor_id',p_actor_id,'pet_id',p_pet_id,'encounters',rows-20,'native_problem_count',(select count(*)from patient_problems p where p.pet_id=p_pet_id and not exists(select 1 from ezyvet_problem_extractions x where x.problem_id=p.id)),'outside_linked_problem_count',(select count(*)from patient_problems p where p.pet_id=p_pet_id and exists(select 1 from ezyvet_problem_extractions x where x.problem_id=p.id)),'has_more',total>20,'next',case when total>20 then jsonb_build_object('visit_at',rows#>'{19,visit_at}','id',rows#>'{19,id}')end);
end $$;
create function public.list_clinical_recaps(p_actor_id uuid,p_pet_id uuid,p_after jsonb default null)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare rows jsonb;total integer;at timestamptz;uid uuid;begin
 perform public.clinical_recap_actor(p_actor_id);if not exists(select 1 from pets p join clients c on c.id=p.client_id where p.id=p_pet_id)then perform public.clinical_recap_refuse('not_found');end if;
 if p_after is not null then perform public.clinical_recap_keys(p_after,array['created_at','id']);uid:=public.clinical_recap_uuid(p_after->'id');begin at:=(p_after->>'created_at')::timestamptz;exception when others then perform public.clinical_recap_refuse('invalid_request');end;if at is null or not isfinite(at)then perform public.clinical_recap_refuse('invalid_request');end if;end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',j.id,'actor_id',j.actor_id,'pet_id',j.pet_id,'policy_version',j.policy_version,'manifest_id',j.manifest_id,'manifest_sha256',j.manifest_sha256,'created_at',public.clinical_recap_timestamp(j.created_at),'captured_at',m.document->'captured_at','previous_job_id',j.previous_job_id,'selection',m.document#>'{source_set,selection}','budgets',m.document#>'{source_set,budgets}','output_id',j.output_id,'review_version',j.review_version,'review_decision',r.decision,'reviewer_id',r.reviewer_id,'reviewed_at',public.clinical_recap_timestamp(r.created_at),'latest_attempt',(select jsonb_build_object('id',a.id,'state',a.state,'created_at',public.clinical_recap_timestamp(a.created_at))from clinical_recap_attempts a where a.job_id=j.id order by a.sequence desc limit 1))order by j.created_at desc,j.id desc),'[]'),count(*)into rows,total from(select *from clinical_recap_jobs where pet_id=p_pet_id and(p_after is null or(created_at,id)<(at,uid))order by created_at desc,id desc limit 21)j join clinical_recap_manifests m on m.id=j.manifest_id left join clinical_recap_reviews r on r.job_id=j.id;
 return jsonb_build_object('actor_id',p_actor_id,'pet_id',p_pet_id,'items',rows-20,'has_more',total>20,'next',case when total>20 then jsonb_build_object('created_at',rows#>'{19,created_at}','id',rows#>'{19,id}')end);
end $$;
create function public.clinical_recap_require_current(j public.clinical_recap_jobs)returns void language plpgsql security definer set search_path=public,pg_temp as $$declare p jsonb;m jsonb;c jsonb;begin
 p:=public.clinical_recap_policy_view();if p->>'status'<>'approved'then perform public.clinical_recap_refuse('policy_unapproved');end if;if(p->>'version')::integer<>j.policy_version then perform public.clinical_recap_refuse('policy_changed');end if;
 select document into m from clinical_recap_manifests where id=j.manifest_id;c:=public.clinical_recap_current(m);if c->>'source_status'<>'current'then perform public.clinical_recap_refuse(case when c->>'source_status'='unavailable'then'source_unavailable'else'source_changed'end,c->'reasons');end if;
 if not public.clinical_recap_session_ok(j.actor_id,j.session_id)then perform public.clinical_recap_refuse('forbidden');end if;
end $$;
create function public.clinical_recap_attempt_intent(p_job_id uuid,p_retry_of uuid,p_reason text,p_ack_cost boolean)returns jsonb language plpgsql immutable set search_path=public,pg_temp as $$begin
 if p_job_id is null or p_reason is null or p_ack_cost is null or(p_retry_of is null and(p_reason<>''or p_ack_cost))or(p_retry_of is not null and(p_reason not in('previous_failure_reviewed','uncertain_outcome_duplicate_charge_authorized','expired_attempt_reviewed')or not p_ack_cost))then perform public.clinical_recap_refuse('invalid_request');end if;return jsonb_build_object('job_id',p_job_id,'retry_of',p_retry_of,'reason',p_reason,'ack_cost',p_ack_cost);end $$;
create function public.claim_clinical_recap(p_actor_id uuid,p_id uuid,p_job_id uuid,p_retry_of uuid default null,p_reason text default'',p_ack_cost boolean default false)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare sid uuid;j clinical_recap_jobs;a clinical_recap_attempts;old clinical_recap_attempts;c clinical_recap_cancellations;intent jsonb;n integer;begin
 sid:=public.clinical_recap_actor(p_actor_id);intent:=public.clinical_recap_attempt_intent(p_job_id,p_retry_of,p_reason,p_ack_cost);if p_id is null then perform public.clinical_recap_refuse('invalid_request');end if;perform public.clinical_recap_lock('policy');perform public.clinical_recap_lock('actor',p_actor_id);perform public.clinical_recap_lock('attempt',p_id);
 select *into j from clinical_recap_jobs where id=p_job_id for update;if not found then perform public.clinical_recap_refuse('not_found');end if;sid:=public.clinical_recap_actor(p_actor_id);if j.actor_id<>p_actor_id then perform public.clinical_recap_refuse('forbidden');end if;
 select *into c from clinical_recap_cancellations where family='attempt'and id=p_id;if found then if c.actor_id<>p_actor_id or c.job_id<>j.id or c.intent is distinct from intent then perform public.clinical_recap_refuse('intent_conflict');end if;perform public.clinical_recap_refuse('action_cancelled');end if;
 select *into a from clinical_recap_attempts where id=p_id;if found then if a.actor_id<>p_actor_id or a.job_id<>j.id or a.intent is distinct from intent then perform public.clinical_recap_refuse('intent_conflict');end if;return public.clinical_recap_attempt_view(a);end if;
 perform public.clinical_recap_require_current(j);if j.output_id is not null then perform public.clinical_recap_refuse('attempt_active');end if;select *into old from clinical_recap_attempts where job_id=j.id order by sequence desc limit 1;
 if found then if p_retry_of is distinct from old.id then perform public.clinical_recap_refuse('retry_not_allowed');end if;if old.state='completed'or(old.state in('claimed','sending')and old.lease_until>clock_timestamp())then perform public.clinical_recap_refuse('attempt_active');end if;
 if old.finished_at is not null and old.failure_details?'retry_after_seconds'and old.finished_at+make_interval(secs=>(old.failure_details->>'retry_after_seconds')::integer)>clock_timestamp()then perform public.clinical_recap_refuse('retry_not_allowed');end if;n:=old.sequence+1;
 else if p_retry_of is not null then perform public.clinical_recap_refuse('retry_not_allowed');end if;n:=1;end if;
 if n>6 or(select count(*)from clinical_recap_attempts where actor_id=p_actor_id and state in('claimed','sending')and lease_until>clock_timestamp())>=2 then perform public.clinical_recap_refuse('rate_limited');end if;sid:=public.clinical_recap_actor(p_actor_id);
 if old.id is not null then update clinical_recap_attempts set state='superseded',finished_at=clock_timestamp()where id=old.id;end if;
 insert into clinical_recap_attempts(id,job_id,actor_id,session_id,sequence,model,state,intent,lease_until)values(p_id,j.id,p_actor_id,sid,n,'gpt-6-luna','claimed',intent,clock_timestamp()+interval'90 seconds')returning *into a;return public.clinical_recap_attempt_view(a);
end $$;
create function public.cancel_clinical_recap_attempt(p_actor_id uuid,p_id uuid,p_job_id uuid,p_retry_of uuid default null,p_reason text default'',p_ack_cost boolean default false)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare sid uuid;j clinical_recap_jobs;a clinical_recap_attempts;c clinical_recap_cancellations;intent jsonb;begin
 sid:=public.clinical_recap_actor(p_actor_id);intent:=public.clinical_recap_attempt_intent(p_job_id,p_retry_of,p_reason,p_ack_cost);if p_id is null then perform public.clinical_recap_refuse('invalid_request');end if;perform public.clinical_recap_lock('policy');perform public.clinical_recap_lock('actor',p_actor_id);perform public.clinical_recap_lock('attempt',p_id);
 select *into j from clinical_recap_jobs where id=p_job_id for update;if not found then perform public.clinical_recap_refuse('not_found');end if;sid:=public.clinical_recap_actor(p_actor_id);if j.actor_id<>p_actor_id then perform public.clinical_recap_refuse('forbidden');end if;
 select *into c from clinical_recap_cancellations where family='attempt'and id=p_id;if found then if c.actor_id<>p_actor_id or c.job_id<>j.id or c.intent is distinct from intent then perform public.clinical_recap_refuse('intent_conflict');end if;return jsonb_build_object('cancelled',true,'job',public.clinical_recap_job_view(j.id));end if;
 select *into a from clinical_recap_attempts where id=p_id for update;if found then if a.actor_id<>p_actor_id or a.job_id<>j.id or a.intent is distinct from intent then perform public.clinical_recap_refuse('intent_conflict');end if;if a.state<>'claimed'then return jsonb_build_object('cancelled',false,'job',public.clinical_recap_job_view(j.id));end if;update clinical_recap_attempts set state='failed',error_code='operator_cancelled_before_dispatch',failure_details='{}',finished_at=clock_timestamp()where id=a.id;end if;
 sid:=public.clinical_recap_actor(p_actor_id);insert into clinical_recap_cancellations(family,id,actor_id,session_id,job_id,intent)values('attempt',p_id,p_actor_id,sid,j.id,intent);return jsonb_build_object('cancelled',true,'job',public.clinical_recap_job_view(j.id));
end $$;
create function public.dispatch_clinical_recap(p_id uuid)returns boolean language plpgsql security definer set search_path=public,pg_temp as $$declare j clinical_recap_jobs;a clinical_recap_attempts;begin
 perform public.clinical_recap_lock('policy');select *into j from clinical_recap_jobs where id=(select job_id from clinical_recap_attempts where id=p_id)for update;select *into a from clinical_recap_attempts where id=p_id for update;if not found then perform public.clinical_recap_refuse('not_found');end if;if a.state<>'claimed'then return false;end if;perform public.clinical_recap_require_current(j);if not public.clinical_recap_session_ok(a.actor_id,a.session_id)then perform public.clinical_recap_refuse('forbidden');end if;if a.lease_until<=clock_timestamp()then perform public.clinical_recap_refuse('retry_not_allowed');end if;update clinical_recap_attempts set state='sending'where id=a.id;return true;
end $$;
create function public.fail_clinical_recap(p_id uuid,p_uncertain boolean,p_code text,p_details jsonb default'{}')returns void language plpgsql security definer set search_path=public,pg_temp as $$declare j clinical_recap_jobs;a clinical_recap_attempts;begin
 if p_uncertain is null or p_code is null or p_code!~'^[a-z_]{1,80}$'or jsonb_typeof(p_details)is distinct from'object'or exists(select 1 from jsonb_object_keys(p_details)k where k<>all(array['http_status','provider_code','request_id','retry_after_seconds']))then perform public.clinical_recap_refuse('invalid_request');end if;
 if(p_details?'http_status'and(public.clinical_recap_integer(p_details->'http_status',100,599)is null))or(p_details?'retry_after_seconds'and(public.clinical_recap_integer(p_details->'retry_after_seconds',0,86400)is null))or(p_details?'request_id'and not coalesce(public.clinical_recap_text(p_details->'request_id',200,false),false))or(p_details?'provider_code'and(jsonb_typeof(p_details->'provider_code')is distinct from'string'or p_details->>'provider_code'!~'^[a-z0-9_]{1,80}$'))then perform public.clinical_recap_refuse('invalid_request');end if;
 perform public.clinical_recap_lock('policy');select *into j from clinical_recap_jobs where id=(select job_id from clinical_recap_attempts where id=p_id)for update;select *into a from clinical_recap_attempts where id=p_id for update;if not found then perform public.clinical_recap_refuse('not_found');end if;if a.state not in('claimed','sending')then return;end if;update clinical_recap_attempts set state=case when p_uncertain then'uncertain'else'failed'end,error_code=p_code,failure_details=p_details,finished_at=clock_timestamp()where id=a.id;
end $$;
create function public.clinical_recap_validate_payload(p jsonb,m jsonb)returns void language plpgsql immutable set search_path=public,pg_temp as $$declare c jsonb;cit jsonb;s jsonb;v jsonb;i integer:=0;status_cite boolean;path text;begin
 perform public.clinical_recap_keys(p,array['claims','review_flags']);if jsonb_typeof(p->'claims')is distinct from'array'or jsonb_array_length(p->'claims')not between 1 and 48 or jsonb_typeof(p->'review_flags')is distinct from'array'or jsonb_array_length(p->'review_flags')>10 then perform public.clinical_recap_refuse('invalid_request');end if;
 for c in select value from jsonb_array_elements(p->'claims')loop i:=i+1;perform public.clinical_recap_keys(c,array['claim_id','category','temporal_status','text','uncertainty','citations']);if c->>'claim_id'is distinct from'claim_'||lpad(i::text,3,'0')or jsonb_typeof(c->'category')is distinct from'string'or c->>'category'not in('history','problem_status','medication_vaccine_mention','conflict')or jsonb_typeof(c->'temporal_status')is distinct from'string'or c->>'temporal_status'not in('historical','recorded_status_as_of_capture','uncertain')or not coalesce(public.clinical_recap_text(c->'text',500),false)or not coalesce(public.clinical_recap_text(c->'uncertainty',500,false),false)or(c->>'temporal_status'='uncertain'and not public.clinical_note_nonblank(c->>'uncertainty'))or(c->>'temporal_status'<>'uncertain'and c->>'uncertainty'<>'')or jsonb_typeof(c->'citations')is distinct from'array'or jsonb_array_length(c->'citations')not between 1 and 4 then perform public.clinical_recap_refuse('invalid_request');end if;
 status_cite:=false;for cit in select value from jsonb_array_elements(c->'citations')loop perform public.clinical_recap_keys(cit,array['source_ref','field_path','quote']);if jsonb_typeof(cit->'source_ref')is distinct from'string'or jsonb_typeof(cit->'field_path')is distinct from'string'or not coalesce(public.clinical_recap_text(cit->'quote',1000),false)then perform public.clinical_recap_refuse('invalid_request');end if;
 select value into s from jsonb_array_elements(m#>'{source_set,sources}')where value->>'ref'=cit->>'source_ref';if not found then perform public.clinical_recap_refuse('invalid_request');end if;path:=cit->>'field_path';
 if(s->>'kind'='signed_encounter'and path not in('fields.subjective','fields.objective','fields.assessment','fields.plan'))or(s->>'kind'='addendum'and path<>'fields.content')or(s->>'kind'='native_problem'and path not in('fields.title','fields.notes','fields.status','fields.importance','fields.onset_date'))then perform public.clinical_recap_refuse('invalid_request');end if;
 v:=s#>string_to_array(path,'.');if jsonb_typeof(v)is distinct from'string'or strpos(v#>>'{}',cit->>'quote')=0 then perform public.clinical_recap_refuse('invalid_request');end if;if s->>'kind'='native_problem'and path='fields.status'then status_cite:=true;end if;end loop;
 if c->>'temporal_status'='recorded_status_as_of_capture'and not status_cite then perform public.clinical_recap_refuse('invalid_request');end if;end loop;
 for v in select value from jsonb_array_elements(p->'review_flags')loop if not coalesce(public.clinical_recap_text(v,500),false)then perform public.clinical_recap_refuse('invalid_request');end if;end loop;
end $$;
create function public.finish_clinical_recap(p_id uuid,p_result jsonb)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare j clinical_recap_jobs;a clinical_recap_attempts;m jsonb;p jsonb;c jsonb;hash text;outcome text;lc jsonb;receipt jsonb;begin
 perform public.clinical_recap_lock('policy');select *into j from clinical_recap_jobs where id=(select job_id from clinical_recap_attempts where id=p_id)for update;select *into a from clinical_recap_attempts where id=p_id for update;if not found then perform public.clinical_recap_refuse('not_found');end if;hash:=public.clinical_recap_hash(p_result);
 if a.result_hash is not null then if a.result_hash is distinct from hash then perform public.clinical_recap_refuse('intent_conflict');end if;return jsonb_build_object('job_id',j.id,'attempt_id',a.id,'retained',a.state='completed','outcome',case when a.state='completed'then'completed'else a.error_code end);end if;
 if a.state<>'sending'or a.lease_until<=clock_timestamp()or j.output_id is not null then perform public.clinical_recap_refuse('retry_not_allowed');end if;
 select document into m from clinical_recap_manifests where id=j.manifest_id;c:=public.clinical_recap_current(m);p:=public.clinical_recap_policy_view();
 outcome:=case when not public.clinical_recap_session_ok(j.actor_id,j.session_id)or not public.clinical_recap_session_ok(a.actor_id,a.session_id)then'forbidden'when p->>'status'<>'approved'or(p->>'version')::integer<>j.policy_version then'policy_changed'else'completed'end;
 if outcome<>'completed'then update clinical_recap_attempts set state='failed',result_hash=hash,error_code=outcome,failure_details='{}',finished_at=clock_timestamp()where id=a.id;return jsonb_build_object('job_id',j.id,'attempt_id',a.id,'retained',false,'outcome',outcome);end if;
 -- The source epoch wait can outlast the provider lease; never retain output on an expired dispatch.
 if a.lease_until<=clock_timestamp()then perform public.clinical_recap_refuse('retry_not_allowed');end if;
 perform public.clinical_recap_keys(p_result,array['request_id','response_id','provider_model','contract_version','prompt_version','manifest_sha256','language_context','payload']);if not coalesce(public.clinical_recap_text(p_result->'request_id',200,false),false)or not coalesce(public.clinical_recap_text(p_result->'response_id',200),false)or not coalesce(public.clinical_recap_text(p_result->'provider_model',200,false),false)or p_result->>'contract_version'is distinct from'clinical-recap-v1'or p_result->>'prompt_version'is distinct from'lrv-recap-claims-v1'or p_result->>'manifest_sha256'is distinct from j.manifest_sha256 then perform public.clinical_recap_refuse('invalid_request');end if;
 lc:=p_result->'language_context';perform public.clinical_recap_keys(lc,array['version','bundle_sha256','request_sha256']);if jsonb_typeof(lc->'version')is distinct from'string'or lc->>'version'!~'^lrv-vet-en-v[1-9][0-9]{0,3}$'or jsonb_typeof(lc->'bundle_sha256')is distinct from'string'or lc->>'bundle_sha256'!~'^[a-f0-9]{64}$'or jsonb_typeof(lc->'request_sha256')is distinct from'string'or lc->>'request_sha256'!~'^[a-f0-9]{64}$'then perform public.clinical_recap_refuse('invalid_request');end if;
 perform public.clinical_recap_validate_payload(p_result->'payload',m);insert into clinical_recap_outputs(id,job_id,manifest_sha256,payload,payload_sha256,provider_manifest)values(a.id,j.id,j.manifest_sha256,p_result->'payload',public.clinical_recap_hash(p_result->'payload'),p_result-'payload');update clinical_recap_jobs set output_id=a.id where id=j.id;update clinical_recap_attempts set state='completed',result=p_result,result_hash=hash,provider_request_id=p_result->>'request_id',finished_at=clock_timestamp()where id=a.id;return jsonb_build_object('job_id',j.id,'attempt_id',a.id,'retained',true,'outcome','completed');
end $$;
create function public.recover_clinical_recap_review(p_actor_id uuid,p_id uuid,p_job_id uuid)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare a clinical_recap_review_actions;c clinical_recap_cancellations;begin
 perform public.clinical_recap_actor(p_actor_id);if p_id is null or p_job_id is null then perform public.clinical_recap_refuse('invalid_request');end if;select *into a from clinical_recap_review_actions where id=p_id;if found then if a.actor_id<>p_actor_id then perform public.clinical_recap_refuse('forbidden');end if;if a.job_id<>p_job_id then perform public.clinical_recap_refuse('intent_conflict');end if;return a.receipt;end if;
 select *into c from clinical_recap_cancellations where family='review'and id=p_id;if found then if c.actor_id<>p_actor_id then perform public.clinical_recap_refuse('forbidden');end if;if c.job_id<>p_job_id then perform public.clinical_recap_refuse('intent_conflict');end if;end if;return null;end $$;
create function public.cancel_clinical_recap_review(p_actor_id uuid,p_id uuid,p_job_id uuid)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare sid uuid;receipt jsonb;begin
 sid:=public.clinical_recap_actor(p_actor_id);perform public.clinical_recap_lock('policy');perform public.clinical_recap_lock('review',p_id);perform 1 from clinical_recap_jobs where id=p_job_id for update;if not found then perform public.clinical_recap_refuse('not_found');end if;sid:=public.clinical_recap_actor(p_actor_id);receipt:=public.recover_clinical_recap_review(p_actor_id,p_id,p_job_id);if receipt is not null then return jsonb_build_object('cancelled',false,'receipt',receipt);end if;
 insert into clinical_recap_cancellations(family,id,actor_id,session_id,job_id)values('review',p_id,p_actor_id,sid,p_job_id)on conflict(family,id)do nothing;return'{"cancelled":true,"receipt":null}'::jsonb;end $$;
create function public.save_clinical_recap_review(p_actor_id uuid,p_id uuid,p_request jsonb)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare sid uuid;job uuid;j clinical_recap_jobs;o clinical_recap_outputs;r clinical_recap_reviews;m jsonb;c jsonb;receipt jsonb;sel jsonb;item jsonb;accepted jsonb:='[]';ids text[]:='{}';decision text;begin
 sid:=public.clinical_recap_actor(p_actor_id);if p_id is null then perform public.clinical_recap_refuse('invalid_request');end if;perform public.clinical_recap_keys(p_request,array['job_id','output_id','expected_output_hash','expected_review_version','manifest_sha256','decision','accepted_claims','review_note','attest_reviewed']);job:=public.clinical_recap_uuid(p_request->'job_id');perform public.clinical_recap_lock('policy');perform public.clinical_recap_lock('review',p_id);select *into j from clinical_recap_jobs where id=job for update;if not found then perform public.clinical_recap_refuse('not_found');end if;sid:=public.clinical_recap_actor(p_actor_id);
 receipt:=public.recover_clinical_recap_review(p_actor_id,p_id,job);if receipt is not null then if(select request from clinical_recap_review_actions where id=p_id)is distinct from p_request then perform public.clinical_recap_refuse('intent_conflict');end if;return receipt;end if;if exists(select 1 from clinical_recap_cancellations where family='review'and id=p_id)then perform public.clinical_recap_refuse('action_cancelled');end if;
 if j.review_version<>public.clinical_recap_integer(p_request->'expected_review_version')or j.review_version<>1 then perform public.clinical_recap_refuse('review_conflict');end if;select *into o from clinical_recap_outputs where id=j.output_id and job_id=j.id;if not found then perform public.clinical_recap_refuse('review_conflict');end if;
 if public.clinical_recap_uuid(p_request->'output_id')<>o.id or p_request->>'expected_output_hash'is distinct from o.payload_sha256 or p_request->>'manifest_sha256'is distinct from j.manifest_sha256 then perform public.clinical_recap_refuse('review_conflict');end if;decision:=p_request->>'decision';sel:=p_request->'accepted_claims';if jsonb_typeof(p_request->'decision')is distinct from'string'or decision not in('accepted','rejected')or jsonb_typeof(sel)is distinct from'array'or jsonb_array_length(sel)>48 or not coalesce(public.clinical_recap_text(p_request->'review_note',2000,false),false)or p_request->'attest_reviewed'is distinct from'true'::jsonb then perform public.clinical_recap_refuse('invalid_request');end if;
 if decision='rejected'then if sel<>'[]'::jsonb or not public.clinical_note_nonblank(p_request->>'review_note')then perform public.clinical_recap_refuse('invalid_request');end if;
 else
  if jsonb_array_length(sel)=0 then perform public.clinical_recap_refuse('invalid_request');end if;
  for item in select value from jsonb_array_elements(sel)loop perform public.clinical_recap_keys(item,array['claim_id','text']);if jsonb_typeof(item->'claim_id')is distinct from'string'or item->>'claim_id'=any(ids)or not coalesce(public.clinical_recap_text(item->'text',500),false)or not exists(select 1 from jsonb_array_elements(o.payload->'claims')where value->>'claim_id'=item->>'claim_id')then perform public.clinical_recap_refuse('invalid_request');end if;ids:=array_append(ids,item->>'claim_id');end loop;
  select document into m from clinical_recap_manifests where id=j.manifest_id;c:=public.clinical_recap_current(m);if c->>'source_status'<>'current'then perform public.clinical_recap_refuse(case when c->>'source_status'='unavailable'then'source_unavailable'else'source_changed'end,c->'reasons');end if;
  if(public.clinical_recap_policy_view()->>'status')<>'approved'then perform public.clinical_recap_refuse('policy_unapproved');end if;if(public.clinical_recap_policy_view()->>'version')::integer<>j.policy_version then perform public.clinical_recap_refuse('policy_changed');end if;
  for c in select value from jsonb_array_elements(o.payload->'claims')loop if c->>'claim_id'=any(ids)then select value into item from jsonb_array_elements(sel)where value->>'claim_id'=c->>'claim_id';accepted:=accepted||jsonb_build_array((c-'text')||jsonb_build_object('proposed_text',c->'text','reviewed_text',item->'text'));end if;end loop;
 end if;
 sid:=public.clinical_recap_actor(p_actor_id);insert into clinical_recap_reviews(id,job_id,output_id,reviewer_id,session_id,decision,accepted_claims,review_note,manifest_sha256,output_sha256)values(p_id,j.id,o.id,p_actor_id,sid,decision,accepted,p_request->>'review_note',j.manifest_sha256,o.payload_sha256)returning *into r;update clinical_recap_jobs set review_version=2 where id=j.id;
 receipt:=jsonb_build_object('id',p_id,'actor_id',p_actor_id,'job_id',j.id,'request_hash',public.clinical_recap_hash(p_request),'review',(to_jsonb(r)-'session_id')||jsonb_build_object('created_at',public.clinical_recap_timestamp(r.created_at)));insert into clinical_recap_review_actions(id,actor_id,session_id,job_id,request,request_hash,receipt)values(p_id,p_actor_id,sid,j.id,p_request,public.clinical_recap_hash(p_request),receipt);return receipt;
end $$;
-- Deliberately explicit ACLs: future public helpers are not implicitly callable.
do $$declare f record;begin for f in select oid,proname from pg_proc where pronamespace='public'::regnamespace and proname in('clinical_recap_row_guard','clinical_recap_hash','clinical_recap_timestamp','clinical_recap_refuse','clinical_recap_keys','clinical_recap_text','clinical_recap_uuid','clinical_recap_integer','clinical_recap_session_ok','clinical_recap_actor','clinical_recap_lock','clinical_recap_epoch_lock','clinical_recap_epoch_changed','clinical_recap_selection','clinical_recap_collect','clinical_recap_current','clinical_recap_policy_view','clinical_recap_attempt_view','clinical_recap_job_view','clinical_recap_job_read','read_clinical_recap_policy','recover_clinical_recap_policy','cancel_clinical_recap_policy','save_clinical_recap_policy','preview_clinical_recap','read_clinical_recap_job','read_clinical_recap_citation','reserve_clinical_recap','cancel_clinical_recap_reservation','list_clinical_recap_sources','list_clinical_recaps','clinical_recap_require_current','clinical_recap_attempt_intent','claim_clinical_recap','cancel_clinical_recap_attempt','dispatch_clinical_recap','fail_clinical_recap','clinical_recap_validate_payload','finish_clinical_recap','recover_clinical_recap_review','cancel_clinical_recap_review','save_clinical_recap_review')loop
 execute format('revoke all on function %s from public,anon,authenticated,service_role',f.oid::regprocedure);
 if f.proname in('read_clinical_recap_policy','recover_clinical_recap_policy','cancel_clinical_recap_policy','save_clinical_recap_policy','preview_clinical_recap','read_clinical_recap_job','read_clinical_recap_citation','reserve_clinical_recap','cancel_clinical_recap_reservation','list_clinical_recap_sources','list_clinical_recaps','claim_clinical_recap','cancel_clinical_recap_attempt','recover_clinical_recap_review','cancel_clinical_recap_review','save_clinical_recap_review')then execute format('grant execute on function %s to authenticated',f.oid::regprocedure);end if;
 if f.proname in('dispatch_clinical_recap','fail_clinical_recap','finish_clinical_recap')then execute format('grant execute on function %s to service_role',f.oid::regprocedure);end if;end loop;end $$;
commit;
